1	//! Release interfaces: bare `release` (local), and the CI plan/execute route.
2	//!
3	//! Bare `release` publishes every unreleased package through the same
4	//! `execute_release` route as `release execute`. The CI route accepts only
5	//! exact package identities and explicit intent, receipt, and orchestration
6	//! revision paths.
7	
8	use std::process::ExitCode;
9	
10	use callisto_graph::commands::{
11	    build_release_intent, build_release_intent_with_artifacts, ci_release_route, derive_release_commit_decision,
12	    derive_selected_release_decision, execute_release, origin_tag_probe, pending_releases, plan_loaded_release,
13	    seal_python_distributions, validate_local_release_intent, validate_release_intent, verify_artifact_manifest,
14	    LocalReleasePlan, LocalReleaseSource, VersionOptions,
15	};
16	use callisto_graph::locate::IgnoreWalkLocator;
17	use callisto_model::{
18	    ApplyPermit, ArtifactDigest, ArtifactManifestEntryV1, ArtifactManifestV1, CommitSha, ExecutionTrustProfileV1,
19	    GitHubArtifactAttestationV1, PackageId, ReleaseArtifactManifestReport, ReleaseDryRunReport, ReleaseExecuteReport,
20	    ReleaseIntentV1, ReleaseIntentV1Wire, ReleaseNothingReport, ReleasePackageId, ReleasePlanReport, ReleaseReceiptV1,
21	    ReleaseReport, ReleaseRunEnvelopeV1,
22	};
23	
24	use crate::cli::{
25	    GlobalArgs, OutputFormat, ReleaseArgs, ReleaseArtifactManifestArgs, ReleaseBuildPythonArgs, ReleaseCommandArgs,
26	    ReleaseExecuteArgs, ReleaseInspectArgs, ReleasePendingArgs, ReleasePlanArgs,
27	};
28	use crate::error::CliError;
29	use crate::output::{emit_line, emit_report, log_line, write_json};
30	use crate::runner::CliCommandRunner;
31	use crate::workspace::{load_workspace, select_inference};
32	
33	pub fn handle(args: ReleaseCommandArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
34	    match args.command {
35	        None => release(&args.packages, args.receipt, global),
36	        Some(ReleaseArgs::Pending(args)) => pending(args, global),
37	        Some(ReleaseArgs::Plan(args)) => plan(args, global),
38	        Some(ReleaseArgs::Inspect(args)) => inspect(args, global),
39	        Some(ReleaseArgs::BuildPython(args)) => build_python(args, global),
40	        Some(ReleaseArgs::ArtifactManifest(args)) => artifact_manifest(args, global),
41	        Some(ReleaseArgs::Execute(args)) => execute(args, global),
42	    }
43	}
44	
45	/// Stderr note when a preview's tags have no `origin` to push to.
46	pub const TAGS_UNBOUND_NOTE: &str =
47	    "note: `origin` has no push URL, so tag operations are unbound; `callisto release` will refuse until one is set";
48	
49	/// Stderr warning for a tag that exists here but not on `origin`.
50	fn tag_missing_from_origin_note(tag: &str) -> String {
51	    format!(
52	        "warning: tag `{tag}` exists here but not on `origin`, so its release may not have finished: check out the \
53	         tagged commit and run `callisto release` again, or push the tag if the release is complete"
54	    )
55	}
56	
57	/// Exact stdout when no package has an unreleased version.
58	pub const NOTHING_TO_RELEASE: &str = "Nothing to release.";
59	
60	fn release(
61	    packages: &[String],
62	    receipt: Option<std::path::PathBuf>,
63	    global: &GlobalArgs,
64	) -> Result<ExitCode, CliError> {
65	    let selections = parse_selections(packages)?;
66	    let runner = CliCommandRunner;
67	    let workspace = load_workspace(global, &runner)?;
68	    let root = workspace.root.clone();
69	    let locator = IgnoreWalkLocator::new(&root);
70	    if let Some(route) = ci_release_route(&workspace)?.filter(|_| !global.dry_run) {
71	        return Err(CliError::ReleaseRequiresCiRoute {
72	            reason: route.to_string(),
73	        });
74	    }
75	    let mode = if global.dry_run {
76	        LocalReleaseSource::Preview
77	    } else {
78	        LocalReleaseSource::Trusted
79	    };
80	    // The one `ls-remote` is network latency; it runs beside the plan rather than before it. Best effort: a tag that
81	    // never reached `origin` is a release that did not finish, whatever the plan says next.
82	    let probe = origin_tag_probe(&workspace).ok().flatten();
83	    let (missing, planned) = std::thread::scope(|scope| {
84	        let missing = probe.as_ref().map(|probe| scope.spawn(|| probe.missing(&runner)));
85	        let planned = plan_loaded_release(&workspace, &selections, mode);
86	        (missing.map(|handle| handle.join().unwrap_or_default()), planned)
87	    });
88	    for tag in missing.unwrap_or_default() {
89	        eprintln!("{}", tag_missing_from_origin_note(&tag));
90	    }
91	    let plan = planned?;
92	    if global.dry_run {
93	        write_release_preview(plan.as_ref(), global.format, &mut std::io::stdout())?;
94	        return Ok(ExitCode::SUCCESS);
95	    }
96	    let Some(plan) = plan else {
97	        print_nothing_to_release(global)?;
98	        return Ok(ExitCode::SUCCESS);
99	    };
100	    for diagnostic in &plan.diagnostics {
101	        eprintln!("warning: {}", diagnostic.message);
102	    }
103	    let intent = plan.intent;
104	    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).expect("non-dry-run permits writes");
105	    // A receipt records only full success; a partial run is recovered by rerunning.
106	    if let Some(path) = &receipt {
107	        callisto_model::atomic::probe_atomic_write(path, &permit).map_err(|source| CliError::Io {
108	            source,
109	            path: Some(path.clone()),
110	        })?;
111	    }
112	    let callisto_model::SourceIdentity::GitCommit { sha } = &intent.snapshot.source else {
113	        return Err(CliError::ReleaseEnvelopeInvalid {
114	            detail: "a local release source must be a Git commit".to_owned(),
115	        });
116	    };
117	    // A local run is its own orchestration, so both revisions are the source commit.
118	    let envelope =
119	        ReleaseRunEnvelopeV1::new(sha.clone(), &intent, None).map_err(|error| CliError::ReleaseEnvelopeInvalid {
120	            detail: error.to_string(),
121	        })?;
122	    let capability = validate_local_release_intent(&root, &locator, &runner, intent)?;
123	    let state = execute_release(&capability, &permit, &envelope, None)?;
124	    let receipt_document =
125	        ReleaseReceiptV1::from_state(capability.intent(), &state).map_err(|error| CliError::ReleaseReceiptIssue {
126	            detail: error.to_string(),
127	        })?;
128	    if let Some(path) = &receipt {
129	        write_receipt(path, &receipt_document, &permit)?;
130	    }
131	    match global.format {
132	        OutputFormat::Json => emit_report(
133	            &mut std::io::stdout(),
134	            &ReleaseReport {
135	                receipt: receipt_document.clone(),
136	            },
137	            global.dry_run,
138	        )?,
139	        OutputFormat::Text => {
140	            let released = capability.intent().decision.entries.len();
141	            match &receipt {
142	                Some(path) => emit_line(&format!(
143	                    "Released {released} package(s); receipt saved to {}",
144	                    path.display()
145	                ))?,
146	                None => emit_line(&format!("Released {released} package(s)"))?,
147	            }
148	        }
149	    }
150	    Ok(ExitCode::SUCCESS)
151	}
152	
153	/// Writes a `release --dry-run` preview of `plan`; `init` shows the same one.
154	pub(crate) fn write_release_preview(
155	    plan: Option<&LocalReleasePlan>,
156	    format: OutputFormat,
157	    out: &mut dyn std::io::Write,
158	) -> Result<(), CliError> {
159	    match (plan, format) {
160	        (None, OutputFormat::Json) => emit_report(
161	            &mut &mut *out,
162	            &ReleaseNothingReport {
163	                nothing_to_release: true,
164	            },
165	            true,
166	        )?,
167	        (None, OutputFormat::Text) => writeln!(out, "{NOTHING_TO_RELEASE}")?,
168	        (Some(plan), OutputFormat::Json) => emit_report(
169	            &mut &mut *out,
170	            &ReleaseDryRunReport {
171	                intent: plan.intent.clone(),
172	                diagnostics: plan.diagnostics.clone(),
173	            },
174	            true,
175	        )?,
176	        (Some(plan), OutputFormat::Text) => {
177	            write!(out, "{}", render_release_plan(&plan.intent, crate::color::enabled()))?
178	        }
179	    }
180	    if let Some(plan) = plan {
181	        if plan.tags_unbound {
182	            eprintln!("{TAGS_UNBOUND_NOTE}");
183	        }
184	        for diagnostic in &plan.diagnostics {
185	            eprintln!("warning: {}", diagnostic.message);
186	        }
187	    }
188	    Ok(())
189	}
190	
191	fn print_nothing_to_release(global: &GlobalArgs) -> Result<(), CliError> {
192	    match global.format {
193	        OutputFormat::Json => emit_report(
194	            &mut std::io::stdout(),
195	            &ReleaseNothingReport {
196	                nothing_to_release: true,
197	            },
198	            global.dry_run,
199	        )?,
200	        OutputFormat::Text => emit_line(NOTHING_TO_RELEASE)?,
201	    }
202	    Ok(())
203	}
204	
205	fn parse_selections(packages: &[String]) -> Result<Vec<ReleasePackageId>, CliError> {
206	    packages.iter().map(|raw| parse_release_selection(raw)).collect()
207	}
208	
209	/// Parses one `--package` release selection: `eco/name` only, the same grammar as the release decision file.
210	fn parse_release_selection(raw: &str) -> Result<ReleasePackageId, CliError> {
211	    callisto_graph::ConfigError::reject_colon_form(raw, "--package").map_err(callisto_graph::GraphError::Config)?;
212	    match PackageId::parse(raw) {
213	        Ok(PackageId::Prefixed { ecosystem, name }) => {
214	            ReleasePackageId::new(ecosystem, name).map_err(|error| CliError::ReleasePackageInvalid {
215	                raw: raw.to_string(),
216	                detail: error.to_string(),
217	            })
218	        }
219	        _ => Err(CliError::ReleasePackageInvalid {
220	            raw: raw.to_string(),
221	            detail: "expected an ecosystem-qualified package id, e.g. `cargo/pkg`".to_string(),
222	        }),
223	    }
224	}
225	
226	/// One-line description of a release operation, shared by both the plain and table renderers.
227	fn describe_operation(operation: &callisto_model::ReleaseOperation) -> String {
228	    match &operation.id().role {
229	        callisto_model::ReleaseOperationRole::RegistryPublish { registry } => {
230	            format!("publish to {}", registry.registry_key().display_name())
231	        }
232	        callisto_model::ReleaseOperationRole::PlatformPublish { registry, platform } => {
233	            format!(
234	                "publish {} to {}",
235	                platform.name(),
236	                registry.registry_key().display_name()
237	            )
238	        }
239	        callisto_model::ReleaseOperationRole::Tag => "create git tag".to_owned(),
240	        callisto_model::ReleaseOperationRole::ForgeRelease => "create GitHub release draft".to_owned(),
241	        callisto_model::ReleaseOperationRole::ArtifactUpload { slot } => {
242	            format!("upload {}", slot.asset_name)
243	        }
244	        callisto_model::ReleaseOperationRole::ForgePublish => "publish GitHub release".to_owned(),
245	    }
246	}
247	
248	/// Human-readable plan: each package and version, then its operations.
249	///
250	/// `use_color` is the one color/table decision ([`crate::color::enabled`]):
251	/// box-drawing table formatting renders only alongside color, never independently.
252	fn render_release_plan(intent: &ReleaseIntentV1, use_color: bool) -> String {
253	    let mut out = String::from("Release plan:\n");
254	    if use_color {
255	        out.push_str(&render_release_plan_table(intent));
256	        return out;
257	    }
258	    for entry in &intent.decision.entries {
259	        out.push_str(&format!("  {} {}\n", entry.package, entry.target_version));
260	        for operation in intent.operations.iter().filter(|op| op.id().package == entry.package) {
261	            out.push_str(&format!("    - {}\n", describe_operation(operation)));
262	        }
263	    }
264	    out
265	}
266	
267	fn render_release_plan_table(intent: &ReleaseIntentV1) -> String {
268	    use comfy_table::{presets::UTF8_FULL, Cell, Color, Table};
269	
270	    let mut table = Table::new();
271	    // Our `use_color` gate is the sole authority -- never let comfy-table's own
272	    // TTY probe override it, so a forced/piped stdout still renders styled.
273	    table.force_no_tty().enforce_styling();
274	    table.load_style(UTF8_FULL);
275	    table.set_header(vec!["Package", "Version", "Operations"]);
276	    for entry in &intent.decision.entries {
277	        let steps: Vec<String> = intent
278	            .operations
279	            .iter()
280	            .filter(|op| op.id().package == entry.package)
281	            .map(describe_operation)
282	            .collect();
283	        table.add_row(vec![
284	            Cell::new(entry.package.to_string()),
285	            Cell::new(entry.target_version.to_string()).fg(Color::Green),
286	            Cell::new(steps.join("\n")),
287	        ]);
288	    }
289	    format!("{table}\n")
290	}
291	
292	/// Exact stdout when every release commit has finished.
293	pub const NO_PENDING_RELEASES: &str = "No pending releases.";
294	
295	fn pending(args: ReleasePendingArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
296	    let from = args
297	        .from
298	        .as_deref()
299	        .map(CommitSha::parse)
300	        .transpose()
301	        .map_err(|error| callisto_graph::GraphError::ReleaseInvariant {
302	            detail: format!("`--from` must be a full commit SHA: {error}"),
303	        })?;
304	    let runner = CliCommandRunner;
305	    let workspace = load_workspace(global, &runner)?;
306	    let found = pending_releases(&workspace, &args.decision, args.limit, from.as_ref())?;
307	    match global.format {
308	        OutputFormat::Json => {
309	            let releases: Vec<_> = found
310	                .iter()
311	                .map(|release| {
312	                    serde_json::json!({
313	                        "source": release.source.as_str(),
314	                        "packages": release
315	                            .packages
316	                            .iter()
317	                            .map(|(package, version)| serde_json::json!({
318	                                "package": package.to_string(),
319	                                "version": version.render(),
320	                            }))
321	                            .collect::<Vec<_>>(),
322	                        "missing": release.missing,
323	                    })
324	                })
325	                .collect();
326	            write_json(&mut std::io::stdout(), &serde_json::json!({ "pending": releases }))?;
327	        }
328	        OutputFormat::Text if found.is_empty() => emit_line(NO_PENDING_RELEASES)?,
329	        OutputFormat::Text => {
330	            emit_line("Pending releases, oldest first:")?;
331	            for release in &found {
332	                let packages: Vec<String> = release
333	                    .packages
334	                    .iter()
335	                    .map(|(package, version)| format!("{package} {}", version.render()))
336	                    .collect();
337	                emit_line(&format!(
338	                    "  {}  {}  (missing: {})",
339	                    &release.source.as_str()[..12],
340	                    packages.join(", "),
341	                    release.missing.join(", ")
342	                ))?;
343	            }
344	        }
345	    }
346	    Ok(ExitCode::SUCCESS)
347	}
348	
349	fn build_python(args: ReleaseBuildPythonArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
350	    if global.dry_run {
351	        return Err(CliError::ReleaseBuildPythonDryRun);
352	    }
353	    let intent = read_intent(&args.intent)?;
354	    if callisto_model::python_publishes(&intent).is_empty() {
355	        return Err(CliError::ReleaseNoPythonPublishes);
356	    }
357	    let outdir = args.artifact_dir.canonicalize().map_err(|source| CliError::Io {
358	        source,
359	        path: Some(args.artifact_dir.clone()),
