378	fn artifact_manifest(args: ReleaseArtifactManifestArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
379	    if global.dry_run {
380	        return Err(CliError::ReleaseArtifactManifestDryRun);
381	    }
382	    let intent = read_intent(&args.intent)?;
383	    if args.seal_python && callisto_model::python_publishes(&intent).is_empty() {
384	        return Err(CliError::ReleaseNoPythonPublishes);
385	    }
386	    if intent.artifact_slots.is_empty() && !args.seal_python {
387	        return Err(CliError::ReleaseNoArtifactSlots);
388	    }
389	    let root = args.artifact_dir.canonicalize().map_err(|source| CliError::Io {
390	        source,
391	        path: Some(args.artifact_dir.clone()),
392	    })?;
393	    if !matches!(intent.snapshot.source, callisto_model::SourceIdentity::GitCommit { .. }) {
394	        return Err(CliError::ReleaseManifestSourceNotGit);
395	    }
396	    let mut entries = Vec::with_capacity(intent.artifact_slots.len());
397	    for slot in &intent.artifact_slots {
398	        let path = root.join(&slot.asset_name);
399	        let metadata = std::fs::symlink_metadata(&path).map_err(|source| CliError::Io {
400	            source,
401	            path: Some(path.clone()),
402	        })?;
403	        if metadata.file_type().is_symlink() || !metadata.is_file() {
404	            return Err(CliError::ReleaseArtifactNotRegularFile {
405	                asset: slot.asset_name.to_string(),
406	                dir: root.display().to_string(),
407	            });
408	        }
409	        let canonical = path.canonicalize().map_err(|source| CliError::Io {
410	            source,
411	            path: Some(path.clone()),
412	        })?;
413	        if !canonical.starts_with(&root) {
414	            return Err(CliError::ReleaseArtifactEscapesDirectory {
415	                asset: slot.asset_name.to_string(),
416	                dir: root.display().to_string(),
417	            });
418	        }
419	        let file = std::fs::File::open(&canonical).map_err(|source| CliError::Io {
420	            source,
421	            path: Some(canonical.clone()),
422	        })?;
423	        let (digest, byte_length) = ArtifactDigest::from_reader(file).map_err(|source| CliError::Io {
424	            source,
425	            path: Some(canonical),
426	        })?;
427	        entries.push(ArtifactManifestEntryV1 {
428	            slot: slot.clone(),
429	            digest: digest.clone(),
430	            byte_length,
431	            attestation: GitHubArtifactAttestationV1 {
432	                repository: slot.attestation_policy.repository.clone(),
433	                workflow_path: slot.attestation_policy.workflow_path.clone(),
434	                workflow_commit: slot.attestation_policy.workflow_commit.clone(),
435	                subject_digest: digest,
436	                source_commit: slot.attestation_policy.workflow_commit.clone(),
437	            },
438	        });
439	    }
440	    let distributions = if args.seal_python {
441	        seal_python_distributions(&intent, &root)?
442	    } else {
443	        Vec::new()
444	    };
445	    let manifest = ArtifactManifestV1::with_distributions(&intent, entries, distributions).map_err(|error| {
446	        CliError::ReleaseManifestInvalid {
447	            detail: error.to_string(),
448	        }
449	    })?;
450	    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).expect("non-dry-run permits writes");
451	    let content = serde_json::to_string_pretty(&manifest).expect("artifact manifest serializes") + "\n";
452	    callisto_model::atomic::atomic_write(&args.out, &content, &permit).map_err(|source| CliError::Io {
453	        source,
454	        path: Some(args.out.clone()),
455	    })?;
456	    match global.format {
457	        OutputFormat::Json => emit_report(
458	            &mut std::io::stdout(),
459	            &ReleaseArtifactManifestReport {
460	                manifest: manifest.clone(),
461	            },
462	            global.dry_run,
463	        )?,
464	        OutputFormat::Text => emit_line(&format!("Artifact manifest saved to {}", args.out.display()))?,
465	    }
466	    Ok(ExitCode::SUCCESS)
467	}
