469	fn plan(args: ReleasePlanArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
470	    if global.dry_run {
471	        return Err(CliError::ReleasePlanDryRun);
472	    }
473	    let runner = CliCommandRunner;
474	    let source_global = source_global(global, args.source_root.as_deref());
475	    let workspace = load_workspace(&source_global, &runner)?;
476	    let decision = match args.from_release_commit.as_deref() {
477	        Some(raw) => {
478	            let commit = callisto_model::CommitSha::parse(raw).map_err(|error| CliError::ReleaseCommitInvalid {
479	                raw: raw.to_owned(),
480	                detail: error.to_string(),
481	            })?;
482	            let decision_path = args
483	                .decision
484	                .as_deref()
485	                .expect("clap requires --decision alongside --from-release-commit");
486	            // The workflow intentionally passes an absolute decision path
487	            // from its separately checked-out release source. Git's commit
488	            // diff and `git show REV:path` both require a repository-relative
489	            // path, so normalize once at the CLI boundary rather than asking
490	            // graph code to infer a caller's checkout layout.
491	            let decision_path = if decision_path.is_absolute() {
492	                let decision_path = dunce::canonicalize(decision_path).map_err(|source| CliError::Io {
493	                    source,
494	                    path: Some(decision_path.to_path_buf()),
495	                })?;
496	                decision_path
497	                    .strip_prefix(&workspace.root)
498	                    .map_err(|_outside_source| CliError::ReleaseDecisionOutsideSource {
499	                        decision: decision_path.display().to_string(),
500	                        root: workspace.root.display().to_string(),
501	                    })?
502	                    .to_path_buf()
503	            } else {
504	                decision_path.to_path_buf()
505	            };
506	            let decision_path = callisto_model::workspace_relative(&decision_path).map_err(|error| {
507	                CliError::ReleaseDecisionPathInvalid {
508	                    path: decision_path.display().to_string(),
509	                    detail: error.to_string(),
510	                }
511	            })?;
512	            derive_release_commit_decision(&workspace, &commit, &decision_path)?
513	        }
514	        None => {
515	            let selections = parse_selections(&args.packages)?;
516	            let inference = select_inference();
517	            let version_plan =
518	                callisto_graph::commands::plan_version(&workspace, &inference, &VersionOptions::default())?;
519	            derive_selected_release_decision(&workspace, &version_plan, &selections)?
520	        }
521	    };
522	    let locator = IgnoreWalkLocator::new(&workspace.root);
523	    let (intent, diagnostics) = match (
524	        &workspace.config.product_release,
525	        &args.orchestration_revision,
526	        &args.artifact_repository,
527	    ) {
528	        (Some(_), Some(revision), Some(repository)) => {
529	            let workflow_commit = callisto_model::CommitSha::parse(revision).map_err(|error| {
530	                CliError::ReleaseOrchestrationRevisionInvalid {
531	                    revision: revision.clone(),
532	                    detail: error.to_string(),
533	                }
534	            })?;
535	            let repository = callisto_model::GitHubRepository::parse(repository).map_err(|error| {
536	                CliError::ReleaseArtifactRepositoryInvalid {
537	                    repository: repository.clone(),
538	                    detail: error.to_string(),
539	                }
540	            })?;
541	            // A missing forge-repository is the graph's error; only the match lives here.
542	            if let Some(configured) = workspace
543	                .config
544	                .product_release
545	                .as_ref()
546	                .and_then(|release| release.forge_repository.as_ref())
547	                .filter(|configured| **configured != repository)
548	            {
549	                return Err(CliError::ReleaseForgeRepositoryMismatch {
550	                    configured: configured.as_slug(),
551	                    requested: repository.as_slug(),
552	                });
553	            }
554	            build_release_intent_with_artifacts(
555	                &workspace.root,
556	                &locator,
557	                &runner,
558	                &decision,
559	                ExecutionTrustProfileV1::GitCommit,
560	                callisto_graph::commands::ArtifactBuildPolicy {
561	                    repository,
562	                    workflow_path: callisto_model::RELEASE_COORDINATOR_WORKFLOW_PATH.to_owned(),
563	                    workflow_commit,
564	                },
565	            )?
566	        }
567	        (Some(_), _, _) => {
568	            return Err(CliError::ReleaseOrchestrationFlagsRequired);
569	        }
570	        (None, revision, repository) => {
571	            // The release workflow always passes both flags, including for sources predating [release].
572	            if revision.is_some() || repository.is_some() {
573	                log_line(
574	                    global.format,
575	                    "notice: --orchestration-revision and --artifact-repository ignored: the source has no [release] section; planning with zero artifact slots",
576	                )?;
577	            }
578	            (
579	                build_release_intent(
580	                    &workspace.root,
581	                    &locator,
582	                    &runner,
583	                    &decision,
584	                    ExecutionTrustProfileV1::GitCommit,
585	                )?,
586	                Vec::new(),
587	            )
588	        }
589	    };
590	    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run)
591	        .expect("release plan rejects --dry-run before creating its explicit output");
592	    write_intent(&args.out, &intent, &permit)?;
593	    for diagnostic in &diagnostics {
594	        eprintln!("warning: {}", diagnostic.message);
595	    }
596	    match global.format {
597	        OutputFormat::Json => emit_report(
598	            &mut std::io::stdout(),
599	            &ReleasePlanReport {
600	                intent: intent.clone(),
601	                diagnostics: diagnostics.clone(),
602	            },
603	            global.dry_run,
604	        )?,
605	        OutputFormat::Text => emit_line(&format!(
606	            "Wrote release intent {} to {}",
607	            intent.digest(),
608	            args.out.display()
609	        ))?,
610	    }
611	    Ok(ExitCode::SUCCESS)
612	}
