623	fn execute(args: ReleaseExecuteArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
624	    // Inputs and the receipt destination are checked before the first effect; a provider failure
625	    // mid-run still leaves landed effects without a receipt, and a rerun adopts them.
626	    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).ok_or(CliError::ReleaseExecuteDryRun)?;
627	    let intent = read_intent(&args.intent)?;
628	    let orchestration_revision = callisto_model::CommitSha::parse(&args.orchestration_revision).map_err(|error| {
629	        CliError::ReleaseOrchestrationRevisionInvalid {
630	            revision: args.orchestration_revision.clone(),
631	            detail: error.to_string(),
632	        }
633	    })?;
634	    callisto_model::atomic::probe_atomic_write(&args.receipt, &permit).map_err(|source| CliError::Io {
635	        source,
636	        path: Some(args.receipt.clone()),
637	    })?;
638	    let manifest = args
639	        .artifact_manifest
640	        .as_deref()
641	        .map(read_artifact_manifest)
642	        .transpose()?;
643	    let sealed_python = manifest
644	        .as_ref()
645	        .is_some_and(|manifest| !manifest.distributions.is_empty());
646	    let verified_artifacts = match (
647	        intent.artifact_slots.is_empty(),
648	        manifest.as_ref(),
649	        args.artifact_dir.as_deref(),
650	    ) {
651	        (true, None, None) => None,
652	        (false, Some(manifest), Some(directory)) | (true, Some(manifest), Some(directory))
653	            if sealed_python || !intent.artifact_slots.is_empty() =>
654	        {
655	            let runner = CliCommandRunner;
656	            Some(verify_artifact_manifest(&intent, manifest, directory, &runner)?)
657	        }
658	        (true, _, _) => {
659	            return Err(CliError::ReleaseUnexpectedArtifactInputs);
660	        }
661	        (false, _, _) => {
662	            return Err(CliError::ReleaseMissingArtifactInputs);
663	        }
664	    };
665	    // The run envelope is minted and cross-checked here, before the first
666	    // effect, and is then the single authority for every fact it carries.
667	    let envelope = ReleaseRunEnvelopeV1::new(
668	        orchestration_revision,
669	        &intent,
670	        verified_artifacts
671	            .as_ref()
672	            .map(|artifacts| artifacts.manifest().digest()),
673	    )
674	    .map_err(|error| CliError::ReleaseEnvelopeInvalid {
675	        detail: error.to_string(),
676	    })?;
677	    let runner = CliCommandRunner;
678	    let source_global = source_global(global, args.source_root.as_deref());
679	    let source_workspace = load_workspace(&source_global, &runner)?;
680	    // A missing forge-repository is the graph's error during intent validation; only the match lives here.
681	    if let Some(configured) = source_workspace
682	        .config
683	        .product_release
684	        .as_ref()
685	        .and_then(|release| release.forge_repository.as_ref())
686	        && let Some(slot) = intent
687	            .artifact_slots
688	            .iter()
689	            .find(|slot| slot.attestation_policy.repository != *configured)
690	    {
691	        return Err(CliError::ReleaseForgeRepositoryMismatch {
692	            configured: configured.as_slug(),
693	            requested: slot.attestation_policy.repository.as_slug(),
694	        });
695	    }
696	    // The workspace root, resolved exactly as `plan` resolves it. Executing
697	    // from a subdirectory must reach the same root, not the process cwd.
698	    let root = source_workspace.root.clone();
699	    let locator = IgnoreWalkLocator::new(&root);
700	    let capability = validate_release_intent(&root, &locator, &runner, intent)?;
701	    let state = execute_release(&capability, &permit, &envelope, verified_artifacts.as_ref())?;
702	    let receipt =
703	        ReleaseReceiptV1::from_state(capability.intent(), &state).map_err(|error| CliError::ReleaseReceiptIssue {
704	            detail: error.to_string(),
705	        })?;
706	    write_receipt(&args.receipt, &receipt, &permit)?;
707	    match global.format {
708	        OutputFormat::Json => emit_report(
709	            &mut std::io::stdout(),
710	            &ReleaseExecuteReport {
711	                receipt: receipt.clone(),
712	            },
713	            global.dry_run,
714	        )?,
715	        OutputFormat::Text => emit_line(&format!("Release receipt saved to {}", args.receipt.display()))?,
716	    }
717	    Ok(ExitCode::SUCCESS)
718	}
