728	fn read_intent(path: &std::path::Path) -> Result<ReleaseIntentV1, CliError> {
729	    let value = read_json_file(path)?;
730	    // A stale intent is the expected failure after a schema bump; name it
731	    // before serde reports it as an opaque parse error.
732	    let found = &value["schemaVersion"];
733	    if found != &serde_json::json!(ReleaseIntentV1::SCHEMA_VERSION) {
734	        return Err(CliError::ReleaseIntentSchemaUnsupported {
735	            path: path.to_path_buf(),
736	            found: found.to_string(),
737	            expected: ReleaseIntentV1::SCHEMA_VERSION,
738	        });
739	    }
740	    let wire: ReleaseIntentV1Wire = serde_json::from_value(value).map_err(|error| CliError::ReleaseIntentInvalid {
741	        path: path.display().to_string(),
742	        detail: error.to_string(),
743	    })?;
744	    Ok(ReleaseIntentV1::from_wire(wire)?)
745	}
