907	        for entry in &intent.decision.entries {
908	            assert!(text.contains(&entry.package.to_string()), "{text}");
909	        }
910	    }
911	
912	    /// `use_color: false` never emits box-drawing characters.
913	    #[test]
914	    fn plan_text_without_color_has_no_box_drawing_chars() {
915	        let intent = sample();
916	        let text = render_release_plan(&intent, false);
