295	fn pending(args: ReleasePendingArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
296	    let from = args
297	        .from
298	        .as_deref()
299	        .map(CommitSha::parse)
300	        .transpose()
301	        .map_err(|error| callisto_graph::GraphError::ReleaseInvariant {
302	            detail: format!("`--from` must be a full commit SHA: {error}"),
303	        })?;
304	    let runner = CliCommandRunner;
305	    let workspace = load_workspace(global, &runner)?;
306	    let found = pending_releases(&workspace, &args.decision, args.limit, from.as_ref())?;
307	    match global.format {
308	        OutputFormat::Json => {
309	            let releases: Vec<_> = found
310	                .iter()
311	                .map(|release| {
312	                    serde_json::json!({
313	                        "source": release.source.as_str(),
314	                        "packages": release
315	                            .packages
316	                            .iter()
317	                            .map(|(package, version)| serde_json::json!({
318	                                "package": package.to_string(),
319	                                "version": version.render(),
320	                            }))
321	                            .collect::<Vec<_>>(),
322	                        "missing": release.missing,
323	                    })
324	                })
325	                .collect();
326	            write_json(&mut std::io::stdout(), &serde_json::json!({ "pending": releases }))?;
327	        }
328	        OutputFormat::Text if found.is_empty() => emit_line(NO_PENDING_RELEASES)?,
329	        OutputFormat::Text => {
330	            emit_line("Pending releases, oldest first:")?;
331	            for release in &found {
332	                let packages: Vec<String> = release
333	                    .packages
334	                    .iter()
335	                    .map(|(package, version)| format!("{package} {}", version.render()))
336	                    .collect();
337	                emit_line(&format!(
338	                    "  {}  {}  (missing: {})",
339	                    &release.source.as_str()[..12],
340	                    packages.join(", "),
341	                    release.missing.join(", ")
342	                ))?;
343	            }
344	        }
345	    }
346	    Ok(ExitCode::SUCCESS)
347	}
