756	        source,
757	        path: Some(path.to_path_buf()),
758	    })?;
759	    serde_json::from_str(&content).map_err(|error| CliError::ReleaseJsonInvalid {
760	        path: path.display().to_string(),
761	        detail: error.to_string(),
762	    })
