52	/// The reason this workspace cannot release locally, if any.
53	pub fn ci_release_route<R: CommandRunner, D: DependencyResolver>(
54	    workspace: &Workspace<'_, R, D>,
55	) -> Result<Option<CiReleaseRoute>, GraphError> {
56	    if workspace
57	        .config
58	        .product_release
59	        .as_ref()
60	        .is_some_and(|release| !release.artifacts.is_empty())
61	    {
62	        return Ok(Some(CiReleaseRoute::ArtifactSlots));
63	    }
64	    if let Some(package) = workspace.graph.packages().find(|package| {
65	        super::derive::is_platform_package(package) || workspace.identity.platforms_of(&package.id).next().is_some()
66	    }) {
67	        return Ok(Some(CiReleaseRoute::PlatformPackage {
68	            package: package.id.display_name(),
69	        }));
70	    }
71	    let matrix = crate::commands::matrix(workspace, &crate::commands::MatrixOptions::default())?;
72	    Ok(matrix
73	        .platform_targets
74	        .keys()
75	        .next()
76	        .map(|package| CiReleaseRoute::PlatformPackage {
77	            package: package.clone(),
78	        }))
79	}
