81	/// What it takes to ask `origin` which of a package's last-release tags it holds.
82	///
83	/// Built from the loaded workspace without touching the network, so the one `git ls-remote` in [`Self::missing`] can
84	/// run beside the rest of the plan.
85	#[derive(Clone, Debug)]
86	pub struct OriginTagProbe {
87	    endpoint: String,
88	    cwd: std::path::PathBuf,
89	    tags: std::collections::BTreeSet<String>,
90	}
91	
92	/// The probe for `workspace`'s last-release tags, or `None` when there is no `origin` push URL or nothing is tagged.
93	pub fn origin_tag_probe<R: CommandRunner, D: DependencyResolver>(
94	    workspace: &Workspace<'_, R, D>,
95	) -> Result<Option<OriginTagProbe>, GraphError> {
96	    let Some(remote) = optional_git_remote(&workspace.root, workspace.runner)? else {
97	        return Ok(None);
98	    };
99	    let tags = workspace.tags()?;
100	    let names: std::collections::BTreeSet<String> = workspace
101	        .graph
102	        .packages()
103	        .filter_map(|package| tags.last_tag(&package.id))
104	        .map(|tag| tag.name.as_str().to_owned())
105	        .collect();
106	    Ok((!names.is_empty()).then(|| OriginTagProbe {
107	        endpoint: remote.endpoint.clone(),
108	        cwd: workspace.root.clone(),
109	        tags: names,
110	    }))
111	}
112	
113	impl OriginTagProbe {
114	    /// The tags that name a package's last release here but are not on `origin`.
115	    ///
116	    /// A release that tagged locally and then failed to push leaves exactly this, and a later rerun on another commit
117	    /// treats the tagged version as finished, so the remote tag and the forge release never happen. Best effort: a
118	    /// remote that cannot be read reports nothing.
119	    pub fn missing<R: CommandRunner + ?Sized>(&self, runner: &R) -> Vec<String> {
120	        let references: Vec<String> = self.tags.iter().map(|name| format!("refs/tags/{name}")).collect();
121	        let mut args = vec!["ls-remote", self.endpoint.as_str()];
122	        args.extend(references.iter().map(String::as_str));
123	        let Ok(output) = runner.run_with_timeout(
124	            super::provider::policy::programs::GIT,
125	            &args,
126	            &self.cwd,
127	            super::provider::policy::timeouts::GIT_LS_REMOTE,
128	        ) else {
129	            return Vec::new();
130	        };
131	        if !output.success() {
132	            return Vec::new();
133	        }
134	        let on_remote: std::collections::BTreeSet<&str> = output
135	            .stdout
136	            .lines()
137	            .filter_map(|line| line.split_once('\t'))
138	            .filter_map(|(_, reference)| reference.strip_prefix("refs/tags/"))
139	            .map(|name| name.strip_suffix("^{}").unwrap_or(name))
140	            .collect();
141	        self.tags
142	            .iter()
143	            .filter(|name| !on_remote.contains(name.as_str()))
144	            .cloned()
145	            .collect()
146	    }
147	}
