149	/// A derived local release.
150	#[derive(Clone, Debug, PartialEq, Eq)]
151	pub struct LocalReleasePlan {
152	    pub intent: ReleaseIntentV1,
153	    /// A preview only: `origin` has no push URL, so tags carry no remote and a run would refuse.
154	    pub tags_unbound: bool,
155	    /// Advisory findings from derivation (e.g. an artifact owner selected without its product).
156	    pub diagnostics: Vec<callisto_model::Diagnostic>,
157	}
