159	/// Derives the intent for every unreleased package (or exactly `selections`).
160	///
161	/// This is the one plan derivation behind both `callisto release --dry-run`
162	/// and `callisto release`; `None` means nothing is unreleased.
163	pub fn plan_local_release<L: ProjectLocator, R: CommandRunner>(
164	    root: &Path,
165	    locator: &L,
166	    runner: &R,
167	    selections: &[ReleasePackageId],
168	    mode: LocalReleaseSource,
169	) -> Result<Option<LocalReleasePlan>, GraphError> {
170	    let root = canonical_root(root)?;
171	    let workspace = Workspace::load(root, locator, runner)?;
172	    plan_release(&workspace, selections, mode, true)
173	}
174	
175	/// The tagged releases on HEAD whose operations are not all observed satisfied: a rerun finishes them.
176	///
177	/// A tag proves only that the tag was created. Releases tagged on an older commit are settled and
178	/// never observed, so only a rerun at the release commit reaches the providers.
179	fn incomplete_tagged_releases<R: CommandRunner, D: DependencyResolver>(
180	    workspace: &Workspace<'_, R, D>,
181	    mode: LocalReleaseSource,
182	) -> Result<std::collections::BTreeSet<ReleasePackageId>, GraphError> {
183	    let head = workspace.git_access().head_sha()?;
184	    let tagged: std::collections::BTreeSet<ReleasePackageId> =
185	        crate::commands::release_decision::releases_tagged_at(workspace, &head)?
186	            .into_iter()
187	            .map(|entry| entry.package)
188	            .collect();
189	    if tagged.is_empty() {
190	        return Ok(tagged);
191	    }
192	    // Without an `origin` push URL a preview cannot observe anything, so it cannot call a tagged release finished.
193	    if mode == LocalReleaseSource::Preview && optional_git_remote(&workspace.root, workspace.runner)?.is_none() {
194	        return Ok(tagged);
195	    }
196	    let profile = ExecutionTrustProfileV1::GitCommit;
197	    let source = match mode {
198	        LocalReleaseSource::Preview => SourceIdentity::GitCommit { sha: head },
199	        LocalReleaseSource::Trusted => observe_source(workspace, profile, ReleaseCheckout::AnyHead)?,
200	    };
201	    // The roster a run would plan with every tagged release still open, so a dependency left untagged by the
202	    // failed run is part of it and the dependency checks see the same packages as the real derivation.
203	    let Some(decision) = crate::commands::release_decision::derive_release_roster(workspace, &[], &tagged)? else {
204	        return Ok(Default::default());
205	    };
206	    let (_, prepared) =
207	        derive_release_intent_with_prepared(workspace, &decision, source, profile, None, &mut Vec::new())?;
208	    Ok(unsatisfied_packages(
209	        &workspace.root,
210	        workspace.runner,
211	        &prepared,
212	        &tagged,
213	    ))
214	}
