216	/// The packages in `decision` this repository has never tagged.
217	fn first_release_packages<R: CommandRunner, D: DependencyResolver>(
218	    workspace: &Workspace<'_, R, D>,
219	    decision: &callisto_model::ReleaseDecisionV1,
220	) -> Result<std::collections::BTreeSet<ReleasePackageId>, GraphError> {
221	    let tags = workspace.tags()?;
222	    Ok(decision
223	        .entries
224	        .iter()
225	        .filter(|entry| {
226	            crate::commands::release_decision::workspace_package(workspace, &entry.package)
227	                .is_some_and(|package| tags.last_tag(&package.id).is_none())
228	        })
229	        .map(|entry| entry.package.clone())
230	        .collect())
231	}
