233	/// Refuses a first release to crates.io of a crate that lacks the metadata crates.io requires.
234	///
235	/// Cargo only warns about it locally; crates.io rejects the upload, which can land after other packages published.
236	fn refuse_a_crate_crates_io_would_reject<R: CommandRunner, D: DependencyResolver>(
237	    workspace: &Workspace<'_, R, D>,
238	    decision: &callisto_model::ReleaseDecisionV1,
239	) -> Result<(), GraphError> {
240	    for id in first_release_packages(workspace, decision)? {
241	        let Some(package) = crate::commands::release_decision::workspace_package(workspace, &id) else {
242	            continue;
243	        };
244	        if !package.publish_to.contains(&PublishTarget::CratesIo) {
245	            continue;
246	        }
247	        let Some(manifest) = package
248	            .canonical_manifests()
249	            .find(|manifest| manifest.format == ManifestFormat::CargoToml)
250	            .map(|manifest| manifest.path.clone())
251	        else {
252	            continue;
253	        };
254	        let Some(text) = callisto_manifests::read_manifest_text(&workspace.root)(&manifest)? else {
255	            continue;
256	        };
257	        let document = callisto_manifests::parse_manifest(&manifest, &text)?;
258	        let root = callisto_manifests::enclosing_workspace_manifest(&workspace.root, &manifest, &document)?;
259	        let root_document = match root {
260	            Some(root) => callisto_manifests::read_manifest_text(&workspace.root)(&root)?
261	                .map(|text| callisto_manifests::parse_manifest(&root, &text))
262	                .transpose()?,
263	            None => None,
264	        };
265	        let missing = callisto_manifests::missing_crates_io_metadata(&document, root_document.as_ref());
266	        if !missing.is_empty() {
267	            return Err(GraphError::ReleaseMetadataMissing {
268	                package: id.to_string(),
269	                missing: missing.join(" or "),
270	            });
271	        }
272	    }
273	    Ok(())
274	}
