276	/// Refuses a first release whose name another project already owns.
277	///
278	/// A package this repository has never tagged has no history here, so a version of it that the registry already holds
279	/// under a different repository is that project's, not ours; adopting it would tag this commit as their release.
280	/// A package that has a tag is left alone: its published versions are its own history.
281	fn refuse_a_name_another_project_owns<R: CommandRunner, D: DependencyResolver>(
282	    workspace: &Workspace<'_, R, D>,
283	    decision: &callisto_model::ReleaseDecisionV1,
284	    source: &SourceIdentity,
285	    profile: ExecutionTrustProfileV1,
286	    mode: LocalReleaseSource,
287	) -> Result<(), GraphError> {
288	    let first_releases = first_release_packages(workspace, decision)?;
289	    // Without an `origin` push URL a preview cannot tell whose repository the registry names.
290	    if first_releases.is_empty()
291	        || (mode == LocalReleaseSource::Preview && optional_git_remote(&workspace.root, workspace.runner)?.is_none())
292	    {
293	        return Ok(());
294	    }
295	    let (_, prepared) =
296	        derive_release_intent_with_prepared(workspace, decision, source.clone(), profile, None, &mut Vec::new())?;
297	    match names_taken_by_other_projects(&workspace.root, workspace.runner, &prepared, &first_releases)?
298	        .into_iter()
299	        .next()
300	    {
301	        Some(taken) => Err(GraphError::ReleaseNameTaken {
302	            package: taken.package.to_string(),
303	            version: taken.version,
304	            registry_repository: taken.registry_repository,
305	            origin: taken.origin,
306	        }),
307	        None => Ok(()),
308	    }
309	}
