311	/// Refuses to tag a version the registry already holds while its package has moved on since the commit that set it.
312	///
313	/// A release that stopped after publishing leaves exactly this state. A rerun on a later commit would tag code that
314	/// was never published, so it finishes from the version commit instead. Nothing is observed unless a package moved.
315	fn refuse_a_published_version_left_behind<R: CommandRunner, D: DependencyResolver>(
316	    workspace: &Workspace<'_, R, D>,
317	    decision: &callisto_model::ReleaseDecisionV1,
318	    resumable: &std::collections::BTreeSet<ReleasePackageId>,
319	    source: &SourceIdentity,
320	    profile: ExecutionTrustProfileV1,
321	    mode: LocalReleaseSource,
322	) -> Result<(), GraphError> {
323	    let moved = super::version_commit::packages_moved_past_their_version(workspace, decision, resumable)?;
324	    // Without an `origin` push URL a preview cannot observe the registry either.
325	    if moved.is_empty()
326	        || (mode == LocalReleaseSource::Preview && optional_git_remote(&workspace.root, workspace.runner)?.is_none())
327	    {
328	        return Ok(());
329	    }
330	    let (_, prepared) =
331	        derive_release_intent_with_prepared(workspace, decision, source.clone(), profile, None, &mut Vec::new())?;
332	    let among = moved.iter().map(|moved| moved.package.clone()).collect();
333	    let published = published_packages(&workspace.root, workspace.runner, &prepared, &among)?;
334	    match moved.into_iter().find(|moved| published.contains(&moved.package)) {
335	        Some(moved) => {
336	            let (since, fix) = match moved.version_commit {
337	                Some(commit) => {
338	                    let short: String = commit.chars().take(12).collect();
339	                    (
340	                        format!("{short}, the commit that set it"),
341	                        format!("Check out {short} (`git checkout --detach {short}`) and run `callisto release` again to finish that release. Releasing from here would tag code that was not published."),
342	                    )
343	                }
344	                None => (
345	                    "the commit that set it, which this history does not show".to_owned(),
346	                    "Check out the commit that was published and run `callisto release` again, or tag that commit by hand. Releasing from here could tag code that was not published.".to_owned(),
347	                ),
348	            };
349	            Err(GraphError::ReleasePublishedVersionMoved {
350	                package: moved.package.to_string(),
351	                version: moved.version,
352	                since,
353	                fix,
354	            })
355	        }
356	        None => Ok(()),
357	    }
358	}
