360	/// [`plan_local_release`] over an already-loaded workspace, e.g. one built from an in-memory config.
361	///
362	/// This looks at no registry for a name another project owns, so a caller that must stay offline, such as the plan
363	/// `init` previews, can use it; [`plan_local_release`] does look.
364	pub fn plan_workspace_release<R: CommandRunner, D: DependencyResolver>(
365	    workspace: &Workspace<'_, R, D>,
366	    selections: &[ReleasePackageId],
367	    mode: LocalReleaseSource,
368	) -> Result<Option<LocalReleasePlan>, GraphError> {
369	    plan_release(workspace, selections, mode, false)
370	}
