372	/// [`plan_local_release`] over an already-loaded workspace: the same plan, including the registry checks, without
373	/// loading the workspace again.
374	pub fn plan_loaded_release<R: CommandRunner, D: DependencyResolver>(
375	    workspace: &Workspace<'_, R, D>,
376	    selections: &[ReleasePackageId],
377	    mode: LocalReleaseSource,
378	) -> Result<Option<LocalReleasePlan>, GraphError> {
379	    plan_release(workspace, selections, mode, true)
380	}
381	
382	fn plan_release<R: CommandRunner, D: DependencyResolver>(
383	    workspace: &Workspace<'_, R, D>,
384	    selections: &[ReleasePackageId],
385	    mode: LocalReleaseSource,
386	    check_taken_names: bool,
387	) -> Result<Option<LocalReleasePlan>, GraphError> {
388	    let resumable = incomplete_tagged_releases(workspace, mode)?;
389	    let Some(decision) = crate::commands::release_decision::derive_release_roster(workspace, selections, &resumable)?
390	    else {
391	        return Ok(None);
392	    };
393	    let profile = ExecutionTrustProfileV1::GitCommit;
394	    let source = match mode {
395	        LocalReleaseSource::Preview => SourceIdentity::GitCommit {
396	            sha: workspace.git_access().head_sha()?,
397	        },
398	        LocalReleaseSource::Trusted => observe_source(workspace, profile, ReleaseCheckout::AnyHead)?,
399	    };
400	    if check_taken_names {
401	        refuse_a_crate_crates_io_would_reject(workspace, &decision)?;
402	        refuse_a_name_another_project_owns(workspace, &decision, &source, profile, mode)?;
403	    }
404	    refuse_a_published_version_left_behind(workspace, &decision, &resumable, &source, profile, mode)?;
405	    // A local run is its own orchestration: slots bind to the source commit.
406	    let artifact_policy = match (&workspace.config.product_release, &source) {
407	        (Some(release), SourceIdentity::GitCommit { sha }) if !release.artifacts.is_empty() => {
408	            release.forge_repository.clone().map(|repository| ArtifactBuildPolicy {
409	                repository,
410	                workflow_path: callisto_model::RELEASE_COORDINATOR_WORKFLOW_PATH.to_owned(),
411	                workflow_commit: sha.clone(),
412	            })
413	        }
414	        _ => None,
415	    };
416	    let remote = match mode {
417	        LocalReleaseSource::Preview => GitRemoteRequirement::OptionalForPreview,
418	        LocalReleaseSource::Trusted => GitRemoteRequirement::Required,
419	    };
420	    let mut diagnostics = Vec::new();
421	    let intent = derive_release_intent(
422	        workspace,
423	        &decision,
424	        source.clone(),
425	        profile,
426	        artifact_policy.as_ref(),
427	        remote,
428	        &mut diagnostics,
429	    )?;
430	    let tags_unbound = mode == LocalReleaseSource::Preview
431	        && intent
432	            .operations
433	            .iter()
434	            .any(|operation| operation.id().role == callisto_model::ReleaseOperationRole::Tag)
435	        && optional_git_remote(&workspace.root, workspace.runner)?.is_none();
436	    if mode == LocalReleaseSource::Trusted && observe_source(workspace, profile, ReleaseCheckout::AnyHead)? != source {
437	        return Err(GraphError::ReleaseIntentStale {
438	            reason: StaleReason::source_identity_changed(),
439	        });
440	    }
441	    Ok(Some(LocalReleasePlan {
442	        intent,
443	        tags_unbound,
444	        diagnostics,
445	    }))
446	}
